let previous=0,accumulator=0,hudClock=0,saveClock=0;
function animate(now){
  const elapsed=Math.min(.1,(now-previous)/1000||0);previous=now;accumulator+=elapsed;
  pollController();const limit=n=>Math.max(-1,Math.min(1,n)),inputX=limit((keys.has(settings.bindings.right)||keys.has('arrowright')?1:0)-(keys.has(settings.bindings.left)||keys.has('arrowleft')?1:0)+stick.x+(controller.x??0)),inputY=limit((keys.has(settings.bindings.down)||keys.has('arrowdown')?1:0)-(keys.has(settings.bindings.up)||keys.has('arrowup')?1:0)+stick.y+(controller.y??0));
  if(run?.phase==='playing'&&!paused&&!document.querySelector('dialog[open]')){dashRequested= dashRequested||!!controller.dash;powerRequested=powerRequested||!!controller.power;}
  if(online.role==='guest'){const accepting=!paused&&!remotePaused&&!onlineWaiting&&run?.phase==='playing'&&!document.querySelector('dialog[open]');online.input({x:accepting?inputX:0,y:accepting?inputY:0,dash:accepting&&dashRequested,power:accepting&&powerRequested,interact:accepting&&(keys.has(settings.bindings.interact)||interactRequested||interactHeld||controller.interact)});dashRequested=false;powerRequested=false;interactRequested=false;}
  if(online.role!=='guest'&&!onlineWaiting&&!networkProblem&&(!online.active||Date.now()-online.lastSuccess<6500)&&run&&!paused&&!menu&&run.phase==='playing'&&!document.querySelector('dialog[open]')&&!imageFailure){const oldPhase=run.phase,oldRoom=run.room,oldKills=run.kills;
    while(accumulator>=1/60&&run.phase==='playing'){stepRun(run,{x:inputX,y:inputY,dash:dashRequested,power:powerRequested,interact:interactRequested||keys.has(settings.bindings.interact)||interactHeld||controller.interact,partner:online.active?{...remoteInput,dash:remotePulse.dash,power:remotePulse.power,morph:remotePulse.morph}:undefined},1/60);remotePulse.dash=false;remotePulse.power=false;remotePulse.morph=null;dashRequested=false;powerRequested=false;interactRequested=false;accumulator-=1/60;}
    if(run.phase!==oldPhase||run.room!==oldRoom){finish();save();renderOverlay();renderRail();if(run.phase==='boon')announce('A memory takes shape. Choose a gift.');if(run.phase==='resolve')announce('The chamber opens. Choose what to leave behind.');if(run.phase==='milestone')announce('The Eye opens. Continue the journey or complete this descent.');}
  }else accumulator=0;
  draw();hudClock+=elapsed;saveClock+=elapsed;if(hudClock>.15){renderRail();hudClock=0;}if(saveClock>2){if(run)save();saveClock=0;}
  requestAnimationFrame(animate);
}

// Agents submit the same bounded movement and choice actions used by a person.
function control(input){if(online.active)throw Error('Scripted multi-frame control is available in solo play. Use live controls in co-op.');if(!run||menu||paused||remotePaused||onlineWaiting||run.phase!=='playing'||document.querySelector('dialog[open]'))throw new Error('The descent is not accepting movement right now.');if(!input||typeof input!=='object'||Array.isArray(input))throw new Error('Expected movement input.');const frames=input.frames??1;if(!Number.isInteger(frames)||frames<1||frames>240||!Number.isFinite(input.x??0)||!Number.isFinite(input.y??0))throw new Error('Use finite x/y movement and 1–240 frames.');for(let i=0;i<frames&&run.phase==='playing';i++)stepRun(run,{x:input.x??0,y:input.y??0,dash:i===0&&!!input.dash,power:i===0&&!!input.power,interact:i===0&&!!input.interact},1/60);changed();draw();return observeRun(run,meta);}
